import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ type: "spring", duration: 0.3, bounce: 0 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ProgressBar as AriaProgressBar,
  type ProgressBarProps as AriaProgressBarProps,
  composeRenderProps,
  Label,
} from "react-aria-components";
import { cn } from "./utils";

export interface ProgressBarProps
  extends Omit<AriaProgressBarProps, "className" | "children"> {
  label?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaProgressBarProps["className"];
  children?: AriaProgressBarProps["children"];
}

export function ProgressBar({
  label,
  className,
  children,
  ...props
}: ProgressBarProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaProgressBar
      {...props}
      data-slot="progress-bar"
      className={composeRenderProps(className, (className) =>
        cn("grid w-full gap-2", className),
      )}
    >
      {children ??
        (({ percentage, valueText, isIndeterminate }) => (
          <>
            <div className="flex justify-between gap-3 text-sm">
              {label && (
                <Label
                  data-slot="progress-bar-label"
                  className="font-medium text-foreground"
                >
                  {label}
                </Label>
              )}
              {!isIndeterminate && (
                <span
                  data-slot="progress-bar-value"
                  className="font-mono tabular-nums text-muted-foreground"
                >
                  {valueText}
                </span>
              )}
            </div>
            <div
              data-slot="progress-bar-track"
              className="h-2 overflow-hidden rounded-full bg-secondary shadow-[var(--shadow-inset)]"
            >
              <motion.div
                data-slot="progress-bar-fill"
                className="h-full rounded-full bg-primary"
                initial={false}
                animate={
                  isIndeterminate
                    ? {
                        width: "33.333%",
                        x: reduceMotion ? "0%" : ["0%", "200%"],
                        opacity: reduceMotion ? 1 : [0.65, 1, 0.65],
                      }
                    : { width: `${percentage}%`, x: "0%", opacity: 1 }
                }
                transition={
                  isIndeterminate && !reduceMotion
                    ? {
                        opacity: {
                          duration: 1.5,
                          repeat: Infinity,
                          ease: "easeInOut",
                        },
                        x: {
                          duration: 1.5,
                          repeat: Infinity,
                          ease: "easeInOut",
                        },
                        width: { duration: 0 },
                      }
                    : { duration: reduceMotion ? 0 : 0.2 }
                }
              />
            </div>
          </>
        ))}
    </AriaProgressBar>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { FileText, Warning, X } from "reicon-react";
import { cn } from "./utils";
import { Button } from "./button";
import { ProgressBar } from "./progress-bar";

export interface AttachmentListProps extends ComponentProps<"ul"> {
  children: ReactNode;
}

export function AttachmentList({
  children,
  className,
  ...props
}: AttachmentListProps) {
  return (
    <ul
      {...props}
      data-slot="attachment-list"
      aria-label={props["aria-label"] ?? "Attachments"}
      className={cn("grid min-w-0 gap-2", className)}
    >
      <AnimatePresence initial={false}>{children}</AnimatePresence>
    </ul>
  );
}

export interface AttachmentProps
  extends Omit<
    ComponentProps<"li">,
    | "children"
    | "onDrag"
    | "onDragStart"
    | "onDragEnd"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
  > {
  name: string;
  size?: number;
  previewUrl?: string;
  status?: "ready" | "uploading" | "uploaded" | "error";
  progress?: number;
  errorMessage?: string;
  onRemove?: () => void;
  onRetry?: () => void;
}

function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function Attachment({
  name,
  size,
  previewUrl,
  status = "ready",
  progress,
  errorMessage,
  onRemove,
  onRetry,
  className,
  ...props
}: AttachmentProps) {
  const reduceMotion = useReducedMotion() === true;
  const isPresent = useIsPresent();
  const statusText =
    status === "uploading"
      ? "Uploading"
      : status === "uploaded"
        ? "Uploaded"
        : status === "error"
          ? (errorMessage ?? "Could not upload")
          : "Ready";

  return (
    <motion.li
      {...props}
      data-slot="attachment"
      data-status={status}
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      layout={reduceMotion ? false : "position"}
      initial={reduceMotion ? false : { opacity: 0, y: 6 }}
      animate={{ opacity: 1, y: 0 }}
      exit={reduceMotion ? { opacity: 1 } : { opacity: 0, y: -6 }}
      transition={{ duration: reduceMotion ? 0 : 0.18, ease: "easeOut" }}
      className={cn(
        "flex min-w-0 items-center gap-3 rounded-lg border border-border bg-card p-2.5 text-sm shadow-[var(--shadow-card)]",
        status === "error" && "border-destructive/60",
        className,
      )}
    >
      <span
        aria-hidden="true"
        data-slot="attachment-preview"
        className="flex size-11 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted text-muted-foreground"
      >
        {previewUrl ? (
          // biome-ignore lint/performance/noImgElement: Files can be object URLs in any React app.
          <img src={previewUrl} alt="" className="size-full object-cover" />
        ) : (
          <FileText size={20} aria-hidden="true" />
        )}
      </span>
      <div className="min-w-0 flex-1">
        <p
          data-slot="attachment-name"
          className="font-medium text-foreground [overflow-wrap:anywhere]"
        >
          {name}
        </p>
        <p
          data-slot="attachment-details"
          className={cn(
            "flex flex-wrap items-center gap-x-1.5 text-xs leading-5 text-muted-foreground",
            status === "error" && "text-destructive",
          )}
        >
          {status === "error" && <Warning size={13} aria-hidden="true" />}
          {size !== undefined && <span>{formatSize(size)}</span>}
          {size !== undefined && <span aria-hidden="true">·</span>}
          <span>{statusText}</span>
        </p>
        {status === "uploading" && (
          <ProgressBar
            aria-label={`${name} upload`}
            value={progress ?? 0}
            isIndeterminate={progress === undefined}
            className="mt-2"
          />
        )}
      </div>
      {status === "error" && onRetry && (
        <Button type="button" variant="ghost" onPress={onRetry}>
          Retry
        </Button>
      )}
      {onRemove && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label={`Remove ${name}`}
          onPress={onRemove}
        >
          <X size={17} aria-hidden="true" />
        </Button>
      )}
    </motion.li>
  );
}

"use client";

import {
  DropZone as AriaDropZone,
  composeRenderProps,
  type DropZoneProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";

export function DropZone({ className, ...props }: DropZoneProps) {
  return (
    <AriaDropZone
      {...props}
      data-slot="drop-zone"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-40 flex-col items-center justify-center gap-3 rounded-xl border border-dashed border-border bg-card p-6 text-center text-sm text-foreground outline-none data-[drop-target]:border-primary data-[drop-target]:bg-accent data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring",
          className,
        ),
      )}
    />
  );
}

export function DropZoneLabel({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="label"
      data-slot="drop-zone-label"
      className={cn("text-sm font-medium text-foreground", className)}
    />
  );
}

"use client";

import {
  FileTrigger as AriaFileTrigger,
  type FileTriggerProps,
} from "react-aria-components";
import { Button } from "./button";

export function FileTrigger({
  label = "Choose files",
  className,
  children,
  ...props
}: FileTriggerProps & {
  label?: string;
  className?: string;
}) {
  return (
    <AriaFileTrigger {...props}>
      {children ?? (
        <Button
          data-slot="file-trigger-button"
          variant="outline"
          className={className}
        >
          {label}
        </Button>
      )}
    </AriaFileTrigger>
  );
}
